     * Reflects the current filter in the address bar.
     *
     * <p>This deliberately calls {@code window.history.replaceState} directly
     * instead of going through {@link com.vaadin.flow.component.page.History}:
     * that class round-trips the URL through {@link QueryParameters}, which
     * percent-encodes the comma between status names. A hand-built query string
     * keeps the {@code status=ACTIVE,CLOSED} form callers are expected to share.
     */
    private void updateUrl() {
        StringBuilder query = new StringBuilder();
        String name = filter.name().trim();
        if (!name.isEmpty()) {
            query.append("name=").append(urlEncode(name));
        }
        if (!filter.statuses().isEmpty()) {
            if (!query.isEmpty()) {
                query.append('&');
            }
            String statuses = Arrays.stream(CustomerStatus.values())
                    .filter(filter.statuses()::contains)
                    .map(Enum::name)
                    .collect(Collectors.joining(","));
            query.append("status=").append(statuses);
        }
        String location = "/" + (query.isEmpty() ? "" : "?" + query);
        getUI().ifPresent(ui -> ui.getPage()
                .executeJs("window.history.replaceState(null, '', $0)", location));
    }

