+package com.example.customers.domain;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertThrows;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import java.util.List;
+import java.util.Set;
+
+import org.junit.jupiter.api.Test;
+
+/**
+ * Exercises the filtering behaviour of {@link CustomerRepository} directly,
+ * without any UI involved.
+ */
+class CustomerRepositoryFilterTest {
+
+    private final QueryLog queryLog = new QueryLog();
+    private final CustomerRepository repository = new CustomerRepository(queryLog);
+
+    @Test
+    void emptyFilterMatchesEveryCustomer() {
+        assertEquals(500, repository.count(CustomerFilter.EMPTY));
+    }
+
+    @Test
+    void nameTermsMatchRegardlessOfOrder() {
+        CustomerFilter adaAal = new CustomerFilter("ada aal", Set.of());
+        CustomerFilter aalAda = new CustomerFilter("aal ada", Set.of());
+        assertEquals(2, repository.count(adaAal));
+        assertEquals(2, repository.count(aalAda));
+    }
+
+    @Test
+    void everyTermMustMatch() {
+        assertEquals(0, repository.count(new CustomerFilter("ada virtanen", Set.of())));
+    }
+
+    @Test
+    void matchingIgnoresCaseAndAccentsBothWays() {
+        int expected = 15; // Mäkinen entries in customers.csv
+        assertEquals(expected, repository.count(new CustomerFilter("makinen", Set.of())));
+        assertEquals(expected, repository.count(new CustomerFilter("MAKINEN", Set.of())));
+        assertEquals(expected, repository.count(new CustomerFilter("mäkinen", Set.of())));
+
+        int josephineExpected = 12; // Joséphine entries in customers.csv
+        assertEquals(josephineExpected, repository.count(new CustomerFilter("josephine", Set.of())));
+    }
+
+    @Test
+    void repeatedAndSurroundingWhitespaceIsNotSignificant() {
+        assertEquals(2, repository.count(new CustomerFilter("  ada   aal  ", Set.of())));
+    }
+
+    @Test
+    void statusAloneFilters() {
+        assertEquals(167, repository.count(new CustomerFilter("", Set.of(CustomerStatus.ACTIVE))));
+        assertEquals(333, repository.count(
+                new CustomerFilter("", Set.of(CustomerStatus.ACTIVE, CustomerStatus.CLOSED))));
+    }
+
+    @Test
+    void noStatusSelectedMeansEveryStatus() {
+        assertEquals(500, repository.count(new CustomerFilter("", Set.of())));
+    }
+
+    @Test
+    void nameAndStatusBothApply() {
+        CustomerFilter filter = new CustomerFilter("mäkinen", Set.of(CustomerStatus.ACTIVE));
+        assertEquals(5, repository.count(filter));
+    }
+
+    @Test
+    void findAllAppliesFilterBeforePagingAndSorting() {
+        CustomerFilter filter = new CustomerFilter("mäkinen", Set.of());
+        List<Customer> page = repository.findAll(
+                0, CustomerRepository.MAX_PAGE_SIZE, List.of(new CustomerSort("firstName", true)), filter);
+
+        assertEquals(15, page.size());
+        for (int i = 0; i + 1 < page.size(); i++) {
+            assertTrue(page.get(i).firstName().compareToIgnoreCase(page.get(i + 1).firstName()) <= 0,
+                    "Sorting must still work while a filter is applied");
+        }
+        page.forEach(c -> assertEquals("Mäkinen", c.lastName()));
+    }
+
+    @Test
+    void filteringStillRefusesOversizedPages() {
+        assertThrows(IllegalArgumentException.class, () -> repository.findAll(
+                0, CustomerRepository.MAX_PAGE_SIZE + 1, List.of(), CustomerFilter.EMPTY));
+    }
+
+    @Test
+    void everyQueryIsStillRecorded() {
+        repository.findAll(0, 50, List.of(), new CustomerFilter("mäkinen", Set.of()));
+        repository.count(new CustomerFilter("mäkinen", Set.of()));
+
+        assertEquals(1, queryLog.pageQueries().size());
+        assertEquals(15, queryLog.pageQueries().get(0).rowsReturned());
+        assertEquals(1, queryLog.countQueries().size());
+        assertEquals(15, queryLog.countQueries().get(0));
+    }
+}
